/**
 * One `uora-anchor-v3` output, pinned byte for byte, and the forgeries a
 * reader must refuse.
 *
 * **This file is duplicated verbatim** in the app repository at
 * `packages/overlay-topics/test/anchor-v3-fixture.ts` and in ts-stack at
 * `packages/overlays/topics/src/uoradpp/__tests__/anchor-v3-fixture.ts`. It is
 * the only thing holding the halves of this format together: this repository
 * writes the output and the others read it, and none can import the other,
 * because a reader is meant to drop into a shared overlay instance that has
 * never heard of this service.
 *
 * A fixture is not an elegant contract. It is, however, the one kind that fails
 * loudly: change the field order, the canonicalisation, the protocol string,
 * the counterparty or the signing preimage on any side, and a suite goes red
 * with a diff you can read.
 *
 * `boundaryShifted` is the half the v2 fixture did not have. Every entry is
 * this output with the subject/type boundary re-cut and the signature copied
 * unchanged. Under v2 all of them verified, because the signature covered the
 * field bytes run together and so said nothing about where a field ended. Under
 * v3 the preimage puts each field behind its length, so every entry below must
 * be rejected. A fixture with only positive vectors certifies that a format
 * accepts what it should, and never that it refuses what it must.
 *
 * Regenerate with `scripts/generate-anchor-v3-fixture.ts`, and change the
 * prefix when the format changes: every published anchor verifies against the
 * layout below.
 *
 * The keys are `77`/`88` repeated to 32 bytes. They are test keys, published
 * here on purpose, and nothing derived from them will ever hold a satoshi.
 */

export const ANCHOR_V3_FIXTURE = {
  /**
   * `PrivateKey.fromHex('77'.repeat(32))`, the anchoring service. Carried in
   * field 6 of the output, so a reader attributes the anchor with nothing
   * configured.
   */
  anchoredBy: '037962d45b38e8bcf82fa8efa8432a01f20c9a53e24c7d3f11df197cb8e70926da',
  /** `PrivateKey.fromHex('88'.repeat(32))`, the issuing brand. */
  issuerKey: '021617d38ed8d8657da4d4761e8057bc396ea9e4b9d29776d4be096016dbd2509b',
  issuerDid: 'did:key:zQ3shNu2oFTbeqexYeunD36my3aQNqEWq8mWD2ACRqQLEipcz',

  subject: 'https://id.gs1.org/01/09506000134352/21/B59E82284DEE',
  attestationId: 'https://id.gs1.org/01/09506000134352/21/B59E82284DEE/state-1',
  uoraType: 'Origin',

  /** The attestation exactly as the app posts it, signed fields included. */
  attestation: {
      "passportId": "https://id.gs1.org/01/09506000134352/21/B59E82284DEE",
      "recordId": "state-1",
      "uora_type": "Origin",
      "timestamp": "2026-08-01T09:00:00.000Z",
      "issuer": "did:key:zQ3shNu2oFTbeqexYeunD36my3aQNqEWq8mWD2ACRqQLEipcz",
      "issuerKeyId": "acct/user_fixture",
      "profile": "battery",
      "profile_version": 2
  },

  /** RFC 8785 over the attestation above. The bytes that get hashed. */
  canonical:
    "{\"issuer\":\"did:key:zQ3shNu2oFTbeqexYeunD36my3aQNqEWq8mWD2ACRqQLEipcz\",\"issuerKeyId\":\"acct/user_fixture\",\"passportId\":\"https://id.gs1.org/01/09506000134352/21/B59E82284DEE\",\"profile\":\"battery\",\"profile_version\":2,\"recordId\":\"state-1\",\"timestamp\":\"2026-08-01T09:00:00.000Z\",\"uora_type\":\"Origin\"}",
  /** SHA-256 of those bytes, which is what field 1 carries. */
  digest: 'e4f663b7e87a40b601716e873a2dec3a37b6a45bd0c8557cb25310ab4e736d11',

  /** The BRC-42 child the output locks to, reproducible from the service key. */
  lockingKey: '030a95609c4125c2f38ec2980c64b3b1af224e65774e48951000ca20d69f8dd371',

  /**
   * The whole output. Deterministic because ECDSA here uses RFC 6979 nonces,
   * so this hex is reproducible on any machine from the keys above.
   */
  lockingScript:
    '',

  /**
   * Forgeries. The output above with the subject/type boundary moved and the
   * signature bytes untouched. Every one of these verified under v2. A reader
   * that admits any of them has lost the guarantee the format exists to make.
   */
  boundaryShifted: [
    '',
    '',
    '',
    '',
  ],
} as const
